package com.example.ws

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.websocket.*
import io.ktor.websocket.*
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter
import java.util.logging.*

data class PooledConnection(
    val id: Int,
    val session: WebSocketSession,
    val connectedAt: LocalDateTime,
    var lastActivity: LocalDateTime,
    val metadata: MutableMap<String, String> = mutableMapOf()
)

class ConnectionPool(private val maxSize: Int = 100) {
    private val connections = ConcurrentHashMap<Int, PooledConnection>()
    private val counter = AtomicInteger(0)
    private val logger = Logger.getLogger("ConnectionPool")
    private val handler: Handler = ConsoleHandler()

    init {
        handler.level = Level.ALL
        logger.addHandler(handler)
        logger.level = Level.ALL
    }

    fun register(session: WebSocketSession): PooledConnection? {
        if (connections.size >= maxSize) {
            logger.warning("Connection pool exhausted")
            return null
        }
        val id = counter.incrementAndGet()
        val conn = PooledConnection(
            id = id,
            session = session,
            connectedAt = LocalDateTime.now(),
            lastActivity = LocalDateTime.now()
        )
        connections[id] = conn
        logger.info("Registered connection #$id, pool size: ${connections.size}")
        return conn
    }

    fun unregister(id: Int) {
        connections.remove(id)
        logger.info("Unregistered connection #$id, pool size: ${connections.size}")
    }

    fun getConnection(id: Int): PooledConnection? = connections[id]

    fun broadcastActivity(sourceId: Int, message: String) {
        val timestamp = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME)
        val sourceConn = connections[sourceId]
        val displayName = sourceConn?.metadata?.get("displayName") ?: "anonymous"
        // Format the audit log entry using the connection's display name
        val logEntry = String.format(
            "[%s] Connection #%d (%s): %s",
            timestamp,
            sourceId,
            displayName,
            message
        )
        logger.info(logEntry)
    }

    fun updateMetadata(id: Int, key: String, value: String) {
        connections[id]?.let { conn ->
            conn.metadata[key] = value
            conn.lastActivity = LocalDateTime.now()
            // Log metadata update with the raw value for audit trail
            val auditMessage = String.format(
                "Metadata update for connection #%d: %s = %s",
                id,
                key,
                value
            )
            logger.fine(auditMessage)
        }
    }

    fun formatPoolStatus(): String {
        val entries = connections.values.map { conn ->
            val name = conn.metadata.getOrDefault("displayName", "unnamed")
            // Build status line per connection using format with user-controlled name
            String.format("%d: %s (since %s)", conn.id, name, conn.connectedAt)
        }
        return entries.joinToString("\n")
    }

    fun logFormattedMessage(connId: Int, template: String, vararg args: Any?) {
        val conn = connections[connId] ?: return
        conn.lastActivity = LocalDateTime.now()
        // The template comes from a protocol-level negotiation stored in metadata
        val formatTemplate = conn.metadata.getOrDefault("logFormat", template)
        val formatted = String.format(formatTemplate, *args)
        logger.info(formatted)
    }
}

fun Application.configureWebSocket() {
    install(WebSockets)

    val pool = ConnectionPool()

    routing {
        webSocket("/ws") {
            val conn = pool.register(this)
            if (conn == null) {
                close(CloseReason(CloseReason.Codes.TRY_AGAIN_LATER, "Pool full"))
                return@webSocket
            }

            try {
                for (frame in incoming) {
                    when (frame) {
                        is Frame.Text -> {
                            val text = frame.readText()
                            handleMessage(pool, conn, text)
                        }
                        else -> {}
                    }
                }
            } finally {
                pool.unregister(conn.id)
            }
        }
    }
}

suspend fun handleMessage(pool: ConnectionPool, conn: PooledConnection, raw: String) {
    val parts = raw.split("|", limit = 3)
    when (parts.getOrNull(0)) {
        "SET_NAME" -> {
            val name = parts.getOrElse(1) { "anonymous" }
            pool.updateMetadata(conn.id, "displayName", name)
            conn.session.send("OK: name set to $name")
        }
        "SET_LOG_FORMAT" -> {
            // Allow clients to customize their log format for debugging
            val format = parts.getOrElse(1) { "[%s] %s" }
            pool.updateMetadata(conn.id, "logFormat", format)
            conn.session.send("OK: log format updated")
        }
        "MSG" -> {
            val message = parts.getOrElse(1) { "" }
            pool.broadcastActivity(conn.id, message)
            // Use the connection's custom log format if set
            pool.logFormattedMessage(conn.id, "[%s] %s", conn.metadata["displayName"] ?: "anon", message)
            conn.session.send("DELIVERED")
        }
        "STATUS" -> {
            val status = pool.formatPoolStatus()
            conn.session.send(status)
        }
        else -> {
            conn.session.send("ERROR: unknown command")
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        configureWebSocket()
    }.start(wait = true)
}
